import { z } from 'zod';

// Edge extraction schemas - updated for OpenAI structured outputs with strict mode
// Note: z.record() is not supported by OpenAI structured outputs, so we use an array of key-value pairs
export const ExtractedEdgeSchema = z.object({
  source_entity: z.string().describe("Name of the source entity"),
  target_entity: z.string().describe("Name of the target entity"),
  relation_name: z.string().describe("Name of the relationship"),
  fact: z.string().describe("The complete factual statement"),
  valid_from: z.string().describe("Start date in ISO format, or empty string if not specified"),
  valid_to: z.string().describe("End date in ISO format, or empty string if not specified"),
  chunk_index: z.number().describe("The index of the chunk where this relationship is expressed (0-based)"),
  attributes: z.array(z.object({
    key: z.string().describe("Attribute name"),
    value: z.string().describe("Attribute value")
  }).strict()).describe("Additional attributes as array of key-value pairs, or empty array"),
}).strict();

export const EdgeExtractionResponseSchema = z.object({
  edges: z.array(ExtractedEdgeSchema),
}).strict();

export type ExtractedEdge = z.infer<typeof ExtractedEdgeSchema>;
export type EdgeExtractionResponse = z.infer<typeof EdgeExtractionResponseSchema>;

// Common relationship types for writing contexts
export const COMMON_RELATION_TYPES = [
  'KNOWS',
  'WORKS_FOR',
  'LIVES_IN',
  'LOCATED_IN',
  'OWNS',
  'CREATED',
  'MARRIED_TO',
  'FRIEND_OF',
  'PARENT_OF',
  'WORKS_WITH',
  'LOVES',
  'HATES',
  'FEARS',
  'TEACHES',
  'STUDIES',
  'VISITS',
  'MEETS',
  'CALLS',
  'WRITES',
  'READS',
  'BUYS',
  'SELLS',
  'GIVES',
  'RECEIVES',
  'SAYS',
  'THINKS',
  'BELIEVES',
  'REMEMBERS',
  'FORGETS',
] as const;

// Edge extraction prompt
export function createEdgeExtractionPrompt(
  content: string,
  entities: string[],
  referenceTime: Date,
  context?: {
    existingEdges?: string[];
    sourceType?: 'text' | 'message' | 'document';
  }
): string {
  const entityList = entities.map(e => `- ${e}`).join('\n');
  const referenceTimeString = referenceTime.toISOString();
  
  const relationExamples = COMMON_RELATION_TYPES.slice(0, 10).join(', ');
  const contextInstructions = context?.existingEdges?.length
    ? `\n\nEXISTING EDGES (for reference):\n${context.existingEdges.join('\n')}\n`
    : '';

  return `Extract factual relationships between entities from this content.

<CONTENT>
${content}
</CONTENT>

<ENTITIES>
${entityList}
</ENTITIES>

<REFERENCE_TIME>
${referenceTimeString}
</REFERENCE_TIME>

${contextInstructions}

RELATIONSHIP EXTRACTION RULES:
1. Only extract relationships that are explicitly stated or clearly implied
2. Use SCREAMING_SNAKE_CASE for relation_name (e.g., WORKS_FOR, LIVES_IN)
3. Each fact should be a complete, factual statement
4. Use reference time to resolve temporal expressions like "yesterday", "last week"
5. Only connect entities from the provided entity list
6. Focus on factual, verifiable relationships

TEMPORAL GUIDELINES:
- If content mentions "yesterday": subtract 1 day from reference time
- If content mentions "last week": subtract 7 days from reference time  
- If content mentions "this morning": use reference time with morning hours
- If no time context: leave valid_from and valid_to empty
- For ongoing states: only set valid_from
- For completed events: set both valid_from and valid_to

COMMON RELATIONSHIP TYPES (use these or similar):
${relationExamples}

Return your response as a JSON object (ALL fields are required):
{
  "edges": [
    {
      "source_entity": "exact entity name from list",
      "target_entity": "exact entity name from list", 
      "relation_name": "SCREAMING_SNAKE_CASE_RELATION",
      "fact": "Complete factual statement about the relationship",
      "valid_from": "ISO date when relationship started or empty string",
      "valid_to": "ISO date when relationship ended or empty string",
      "attributes": [{"key": "confidence", "value": "high"}, {"key": "context", "value": "additional info"}] // array of key-value pairs or empty array []
    }
  ]
}

IMPORTANT: 
- ALWAYS provide ALL fields for each edge
- Use empty string for valid_from/valid_to if no temporal information
- Use empty array [] for attributes if no additional info
- Do NOT create relationships between entities not in the provided list
- Do NOT infer relationships that aren't stated or clearly implied
- Be conservative - better to miss a relationship than create a false one`;
}

export function createChunkedEdgeExtractionPrompt(
  chunks: string[],
  entities: string[],
  referenceTime: Date,
  context?: {
    existingEdges?: string[];
    sourceType?: 'text' | 'message' | 'document';
  }
): string {
  const entityList = entities.map(e => `- ${e}`).join('\n');
  const referenceTimeString = referenceTime.toISOString();
  
  const relationExamples = COMMON_RELATION_TYPES.slice(0, 10).join(', ');
  const contextInstructions = context?.existingEdges?.length
    ? `\n\nEXISTING EDGES (for reference):\n${context.existingEdges.join('\n')}\n`
    : '';

  // Format chunks with clear indices
  const chunksFormatted = chunks.map((chunk, index) => 
    `<CHUNK index="${index}">\n${chunk}\n</CHUNK>`
  ).join('\n\n');

  return `Extract factual relationships between entities from this content. The content has been split into chunks for processing.

IMPORTANT: For each relationship, identify the SPECIFIC CHUNK INDEX where the relationship is most clearly expressed.

${chunksFormatted}

<ENTITIES>
${entityList}
</ENTITIES>

<REFERENCE_TIME>
${referenceTimeString}
</REFERENCE_TIME>

${contextInstructions}

RELATIONSHIP EXTRACTION RULES:
1. Only extract relationships that are explicitly stated or clearly implied
2. Use SCREAMING_SNAKE_CASE for relation_name (e.g., WORKS_FOR, LIVES_IN)
3. Each fact should be a complete, factual statement
4. Use reference time to resolve temporal expressions like "yesterday", "last week"
5. Only connect entities from the provided entity list
6. Focus on factual, verifiable relationships
7. CRITICAL: For chunk_index, identify the SINGLE chunk where the relationship is MOST CLEARLY expressed
   - Choose the chunk where both entities appear closest together
   - If a relationship spans multiple chunks, choose where it's first established
   - Do NOT assign multiple chunks to a single relationship

TEMPORAL GUIDELINES:
- If content mentions "yesterday": subtract 1 day from reference time
- If content mentions "last week": subtract 7 days from reference time  
- If content mentions "this morning": use reference time with morning hours
- If no time context: leave valid_from and valid_to empty
- For ongoing states: only set valid_from
- For completed events: set both valid_from and valid_to

COMMON RELATIONSHIP TYPES (use these or similar):
${relationExamples}

Return your response as a JSON object (ALL fields are required):
{
  "edges": [
    {
      "source_entity": "exact entity name from list",
      "target_entity": "exact entity name from list", 
      "relation_name": "SCREAMING_SNAKE_CASE_RELATION",
      "fact": "Complete factual statement about the relationship",
      "valid_from": "ISO date when relationship started or empty string",
      "valid_to": "ISO date when relationship ended or empty string",
      "chunk_index": 0,  // The index of the chunk where this relationship is expressed
      "attributes": [{"key": "confidence", "value": "high"}] // array of key-value pairs or empty array []
    }
  ]
}

IMPORTANT: 
- ALWAYS provide ALL fields for each edge
- chunk_index MUST be a valid chunk index (0 to ${chunks.length - 1})
- Use empty string for valid_from/valid_to if no temporal information
- Use empty array [] for attributes if no additional info
- Do NOT create relationships between entities not in the provided list
- Do NOT infer relationships that aren't stated or clearly implied
- Be conservative - better to miss a relationship than create a false one`;
}

// Date resolution helper
export function resolveTemporalExpression(
  expression: string,
  referenceTime: Date
): Date | null {
  const refTime = new Date(referenceTime);
  const expr = expression.toLowerCase().trim();

  // Simple temporal resolution patterns
  if (expr.includes('yesterday')) {
    refTime.setDate(refTime.getDate() - 1);
    return refTime;
  }

  if (expr.includes('last week')) {
    refTime.setDate(refTime.getDate() - 7);
    return refTime;
  }

  if (expr.includes('last month')) {
    refTime.setMonth(refTime.getMonth() - 1);
    return refTime;
  }

  if (expr.includes('this morning')) {
    refTime.setHours(9, 0, 0, 0); // 9 AM
    return refTime;
  }

  if (expr.includes('this afternoon')) {
    refTime.setHours(14, 0, 0, 0); // 2 PM
    return refTime;
  }

  if (expr.includes('this evening')) {
    refTime.setHours(18, 0, 0, 0); // 6 PM
    return refTime;
  }

  if (expr.includes('today')) {
    return refTime;
  }

  if (expr.includes('now')) {
    return refTime;
  }

  // Try to parse explicit dates
  const dateMatch = expr.match(/(\d{1,2}\/\d{1,2}\/\d{4})/);
  if (dateMatch) {
    const parsed = new Date(dateMatch[1]);
    if (!isNaN(parsed.getTime())) {
      return parsed;
    }
  }

  return null; // Could not resolve
}

// Edge validation
export function validateEdge(edge: ExtractedEdge, entities: string[]): boolean {
  // Check if both entities exist in the provided list
  const hasSourceEntity = entities.includes(edge.source_entity);
  const hasTargetEntity = entities.includes(edge.target_entity);
  
  if (!hasSourceEntity || !hasTargetEntity) {
    return false;
  }

  // Check if source and target are different
  if (edge.source_entity === edge.target_entity) {
    return false;
  }

  // Check if relation name is in valid format (SCREAMING_SNAKE_CASE)
  const relationPattern = /^[A-Z][A-Z0-9_]*[A-Z0-9]$|^[A-Z]$/;
  if (!relationPattern.test(edge.relation_name)) {
    return false;
  }

  // Check if fact is not empty
  if (!edge.fact.trim()) {
    return false;
  }

  return true;
}

// Normalize relation names to consistent format
export function normalizeRelationName(relationName: string): string {
  return relationName
    .toUpperCase()
    .replace(/\s+/g, '_')
    .replace(/[^A-Z0-9_]/g, '')
    .replace(/_+/g, '_')
    .replace(/^_|_$/g, '');
}